    `status_reason` from {{ ref('int_opportunity_stage_visits') }} where model_run_id={{ ch_literal(var('model_run_id','parse_only')) }}), originals as (select tenant_id,opportunity_id,min(valid_from_at) as first_at,argMin(tuple(created_at),valid_from_at).1 as created_at,argMin(tuple(source_version_keys),valid_from_at).1 as creation_keys from p group by tenant_id,opportunity_id), terminals as (select tenant_id,opportunity_id,minOrNullIf(first_observed_at,stage_id in (1,14,13,27,3,9,2,7)) as first_terminal,minOrNullIf(first_observed_at,stage_id in (1,14)) as first_win from v group by tenant_id,opportunity_id), event_rows as (select tenant_id,opportunity_id,'pipeline_created' as kind,created_at as at,first_at as observed,'creation' as origin,CAST(NULL AS Nullable(String)) as visit_key,CAST(NULL AS Nullable(Int64)) as from_stage,CAST(NULL AS Nullable(Int64)) as to_stage,'business_created' as basis from originals union all select tenant_id,opportunity_id,'stage_entered' as kind,entered_at as at,first_observed_at as observed,visit_key as origin,visit_key,previous_stage_id as from_stage,stage_id as to_stage,if(entered_at is null,'unknown',event_time_basis) as basis from v union all select tenant_id,opportunity_id,'stage_exited' as kind,exited_at as at,first_observed_at as observed,visit_key as origin,visit_key,stage_id as from_stage,next_stage_id as to_stage,'cdc_transition_proxy' as basis from v where exited_at is not null union all select tenant_id,opportunity_id,multiIf(stage_id=1,'signed',stage_id in (13,27),'lost',stage_id in (3,9),'abandoned','unqualified') as kind,entered_at as at,first_observed_at as observed,visit_key as origin,visit_key,previous_stage_id as from_stage,stage_id as to_stage,if(entered_at is null,'unknown',event_time_basis) as basis from v where stage_id in (1,13,27,3,9,2,7)),
business as (select
    CAST(greatest(x.observed,greatest(p.source_published_at,pf.source_published_at,pt.source_published_at)) AS Nullable(DateTime64(3,'UTC'))) AS `source_published_at`,
    CAST(arraySort(arrayDistinct(arrayConcat(arraySort(arrayDistinct(arrayFilter(x->x is not null,arrayConcat(ifNull(p.source_version_keys,[]),ifNull(pf.source_version_keys,[]),ifNull(pt.source_version_keys,[]))))),ifNull(o.creation_keys,[])))) AS Array(String)) AS `source_version_keys`,
    CAST(x.tenant_id AS String) AS `tenant_id`,
    CAST(x.opportunity_id AS Int64) AS `opportunity_id`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('opportunity_v1',tuple('tenant_id','String',if(isNull(x.tenant_id),'1','0'),ifNull(toString(x.tenant_id),'')),tuple('opportunity_id','Int64',if(isNull(x.opportunity_id),'1','0'),ifNull(toString(x.opportunity_id),'')))))))) AS String) AS `opportunity_key`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('event_v1',tuple('opportunity_key','String',if(isNull(opportunity_key),'1','0'),ifNull(toString(opportunity_key),'')),tuple('event_type','String',if(isNull(x.kind),'1','0'),ifNull(toString(x.kind),'')),tuple('event_origin_key','String',if(isNull(x.origin),'1','0'),ifNull(toString(x.origin),'')))))))) AS String) AS `event_key`,
    CAST(x.origin AS String) AS `event_origin_key`,
    CAST(x.visit_key AS Nullable(String)) AS `visit_key`,
    CAST(x.kind AS String) AS `event_type`,
    CAST(x.at AS Nullable(DateTime64(3,'UTC'))) AS `event_at`,
    CAST(x.observed AS DateTime64(3,'UTC')) AS `event_observed_at`,
    CAST(x.basis AS String) AS `event_time_basis`,
    CAST(toYYYYMMDD(toDate(x.at,'Europe/Paris')) AS Nullable(UInt32)) AS `event_date_key`,
    CAST(x.from_stage AS Nullable(Int64)) AS `from_stage_id`,
    CAST(x.to_stage AS Nullable(Int64)) AS `to_stage_id`,
    CAST(if(x.from_stage=pf.stage_id,pf.stage_version_key,NULL) AS Nullable(String)) AS `from_stage_version_key`,
    CAST(if(x.to_stage=pt.stage_id,pt.stage_version_key,NULL) AS Nullable(String)) AS `to_stage_version_key`,
    CAST(o.created_at AS Nullable(DateTime64(3,'UTC'))) AS `created_at`,
    CAST(toStartOfMonth(toDate(o.created_at,'Europe/Paris')) AS Nullable(Date)) AS `cohort_month`,
    CAST(p.company_id AS Nullable(Int64)) AS `company_id`,
    CAST(p.company_key AS Nullable(String)) AS `company_key`,
    CAST(p.company_version_key AS Nullable(String)) AS `company_version_key`,
    CAST(p.sale_type_id AS Nullable(Int64)) AS `sale_type_id`,
    CAST(p.sale_type_key AS Nullable(String)) AS `sale_type_key`,
    CAST(p.sale_type_version_key AS Nullable(String)) AS `sale_type_version_key`,
    CAST(p.employee_id AS Nullable(Int64)) AS `employee_id`,
    CAST(p.employee_key AS Nullable(String)) AS `employee_key`,
    CAST(p.employee_version_key AS Nullable(String)) AS `employee_version_key`,
    CAST(p.team_id AS Nullable(Int64)) AS `team_id`,
    CAST(p.team_key AS Nullable(String)) AS `team_key`,
    CAST(p.team_version_key AS Nullable(String)) AS `team_version_key`,
    CAST(p.sales_segment AS Nullable(String)) AS `sales_segment`,
    CAST(ifNull(p.is_team_calculable,false) AS Bool) AS `is_team_calculable`,
    CAST(p.acquisition_channel_key AS Nullable(String)) AS `acquisition_channel_key`,
    CAST(p.channel_version_key AS Nullable(String)) AS `channel_version_key`,
    CAST(p.channel_candidate_code AS Nullable(String)) AS `channel_candidate_code`,
    CAST(ifNull(p.is_channel_calculable,false) AS Bool) AS `is_channel_calculable`,
    CAST(ifNull(p.attribution_status,'missing_temporal_context') AS String) AS `attribution_status`,
    CAST(if(x.at is null,NULL,true) AS Nullable(Bool)) AS `is_event_time_accepted`,
    CAST(if(is_contribution_eligible is null,NULL,toUInt8(is_contribution_eligible)) AS Nullable(UInt8)) AS `nb_events`,
    CAST(if(x.kind='pipeline_created',p.pipeline_amount,NULL) AS Nullable(Decimal(38,4))) AS `generated_pipeline_amount_candidate`,
    CAST(if(x.kind='pipeline_created' and is_contribution_eligible,p.pipeline_amount,NULL) AS Nullable(Decimal(38,4))) AS `sum_generated_pipeline_amount`,
    CAST(NULL AS Nullable(Decimal(38,4))) AS `sum_signed_mrr`,
    CAST('crm_estimated_unconfirmed' AS String) AS `amount_basis`,
    CAST('EUR' AS Nullable(String)) AS `currency_code`,
    CAST(o.created_at AS Nullable(DateTime64(3,'UTC'))) AS `cycle_started_at`,
    CAST(if(x.observed=t.first_terminal and x.at is not null and o.created_at<=x.at and (x.kind in ('signed','lost','abandoned','unqualified') or (x.kind='stage_entered' and x.to_stage=14)),dateDiff('millisecond',o.created_at,x.at)/1000.,NULL) AS Nullable(Float64)) AS `completed_cycle_duration_seconds`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('counting_scope_v1',tuple('opportunity_key','String',if(isNull(opportunity_key),'1','0'),ifNull(toString(opportunity_key),'')),tuple('event_type','String',if(isNull(x.kind),'1','0'),ifNull(toString(x.kind),'')))))))) AS String) AS `counting_scope_key`,
    CAST(multiIf(x.at is null,NULL,p.sale_type_id is null,NULL,p.sale_type_id not in (4,7),false,x.kind='signed',x.observed=t.first_win,true) AS Nullable(Bool)) AS `is_contribution_eligible`,
    CAST(if(x.at is null or p.period_key is null,'partial','ready') AS String) AS `calculation_status`,
    CAST(multiIf(x.at is null,'unknown_event_date',p.period_key is null,'incomplete_history',NULL) AS Nullable(String)) AS `status_reason`
from event_rows x left join p on x.tenant_id=p.tenant_id and x.opportunity_id=p.opportunity_id and if(x.kind='stage_exited',x.at>p.valid_from_at and x.at<=p.valid_to_at,x.at>=p.valid_from_at and (p.valid_to_at is null or x.at<p.valid_to_at)) left join terminals t on x.tenant_id=t.tenant_id and x.opportunity_id=t.opportunity_id left join originals o on x.tenant_id=o.tenant_id and x.opportunity_id=o.opportunity_id left join p pf on x.tenant_id=pf.tenant_id and x.opportunity_id=pf.opportunity_id and x.at>pf.valid_from_at and x.at<=pf.valid_to_at left join p pt on x.tenant_id=pt.tenant_id and x.opportunity_id=pt.opportunity_id and x.at>=pt.valid_from_at and (pt.valid_to_at is null or x.at<pt.valid_to_at)),
